assert len(N) == 30, len(N)
out = pathlib.Path(__file__).with_name("queue.json")
rows = [r for r in json.loads(out.read_text(encoding="utf-8")) if r["Night"] <= 30]
assert len(rows) == 30, "run content_1_30.py first"
for i, d in enumerate(N, 31):
    rows.append({"Id": f"DD{i:03d}", "Night": i, "Date": (START + datetime.timedelta(days=i - 1)).isoformat(),
                 **d, "approved": APPROVED})
out.write_text(json.dumps(rows, indent=1, ensure_ascii=False), encoding="utf-8")
print(len(rows), "nights in", out)
